Q: Get a value of non-default-constructible type `T` from a byte array without undefined behavior A: <p>Why are you passing a <em>copy of the object</em> to Rust, and then passing that copy back to C++? Why not just pass around a <em>pointer</em> to the original object instead?</p>
<p>IOW, given a <code>T</code> object, get a <code>T*</code> pointer to it, convert that pointer into the byte array, pass it around, and then convert the byte array back into a <code>T*</code> to access the original <code>T</code>.</p>
<pre class="lang-cpp prettyprint-override"><code>T obj;
...
T* ptrObj = &amp;obj;
std::byte arr[sizeof(ptrObj)];
memcpy(arr, &amp;ptrObj, sizeof(ptrObj));
...
std::byte *ptr = ...;
T* pObj;
memcpy(&amp;pObj, ptr, sizeof(pObj));
// use pObj as needed...
</code></pre>

Q: Bad DFM streaming of a TForm displayed in CEF4Delphi TChromium.OnDownloadUpdated event A: <p>As pointed by @Sebastian Z, the problem was that I was creating the form in a separate thread.</p>
<p>I changed the handling of the download to the main thread using PostMessage</p>
<pre><code>procedure TMainForm.ChromiumDownloadUpdated(Sender: TObject;
  const browser: ICefBrowser; const downloadItem: ICefDownloadItem;
  const callback: ICefDownloadItemCallback);
begin

  if downloadItem.IsComplete then
  begin
    FOriginalFilename := downloadItem.SuggestedFileName;
    if FOriginalFilename = '' then
      FOriginalFilename := ExtractFileName(downloadItem.GetFullPath);

    FBytesRecibidos := downloadItem.ReceivedBytes;
    FRutaCompletaDescarga := downloadItem.GetFullPath;

    // 5514 - 'Descarga completa del documento %1. Seleccione una opción, por favor...'
    ActualizarStatusBar(MensajeQuiter5000(5514, [FOriginalFilename]), True);

    // preparar descarga completa
    PostMessage(Handle, CEF_AFTERDOWNLOAD, 0, 0);
  end;
end;




    procedure NotificacionDescargaFinalizada(var aMessage : TMessage); message CEF_AFTERDOWNLOAD;


procedure TMainForm.NotificacionDescargaFinalizada(var aMessage: TMessage);
var
  FileIcon: TIcon;
  Descripcion: string;
  openSaveForm: TOpenSaveForm;
  c: TComponent;
  i: integer;
begin
    FileIcon := TIcon.Create;
    openSaveForm := TOpenSaveForm.Create(self);
    try
      try
        openSaveForm.LabelFilename.Caption := OpenSaveFormCaptionMsg(FOriginalFilename, FBytesRecibidos);

        GetFileIconAndDescription(FRutaCompletaDescarga, FileIcon, Descripcion);
        openSaveForm.RadioButtonOpen.Caption := openSaveForm.RadioButtonOpen.Caption + ' ' + Descripcion;
        openSaveForm.FileIcon.Picture.Icon := FileIcon;

        if openSaveForm.ShowModal = mrOk then
          ChooseShowSaveDialog(FRutaCompletaDescarga, openSaveForm.RadioButtonSave.Checked);
      except
        on E: Exception do
          ShowMessage('Excepcion opensaveform: ' + E.Message);
      end;
    finally
      openSaveForm.Free;
      FileIcon.Free;
    end;
end;
</code></pre>
<p>Now the form is working fine.</p>
